SourceCode.Declaration:
internal class GUPBasePriceRawDataProvider
{
    private GUPVendListPriceTmp vendListPriceTmp;
    private GUPPriceTermAgreementTmp priceTermAgreementTmp;
    private GUPVendListPriceSplitDateTmp vendListPriceSplitDateTmp;
    private GUPVendListPriceAndPriceTermAgreementTmp vendListPricePriceTermAgreementRelationTmp;
    private GUPInventDimMatchResultTmp inventDimMatchResultTmp;
    private Map inventDimMap;
    private Map pricingRuleMap;
    private Map queryMap;
    private GUPBasePriceRawData basePriceRawData;
    private Set itemsToBeCalculated;
    private static int ITEMS_PER_GROUP = 500;
    private static int PRICE_TERM_PER_GROUP = 500;

}

Method.Source:
public static GUPBasePriceRawDataProvider instance(InventSiteId _siteId, FromDate _calculationDate)
{
    return new GUPBasePriceRawDataProvider(_siteId, _calculationDate);
}

private void new(InventSiteId _siteId, FromDate _calculationDate)
{
    basePriceRawData = GUPBasePriceRawData::instance();
    basePriceRawData.paramInventSiteId(_siteId);
    basePriceRawData.paramCalculationDate(_calculationDate);

    inventDimMap = new Map(Types::String, Types::Record);
    pricingRuleMap = new Map(Types::Int64, Types::Record);
    queryMap = new Map(Types::Int64, Types::AnyType);
    itemsToBeCalculated = new Set(Types::String);
}

public GUPBasePriceRawData initializeBasePriceRawData()
{
    this.prepareVendListPriceTmp();
    this.preparePriceTermAgreementTmp();
    this.prepareVendListPriceAndPriceTermAgreementTmp();

    basePriceRawData.paramVendListPriceTmp(vendListPriceTmp);
    basePriceRawData.paramPriceTermAgreementTmp(priceTermAgreementTmp);
    basePriceRawData.paramVendListPriceSplitDateTmp(vendListPriceSplitDateTmp);
    basePriceRawData.paramVendListPriceAndPriceTermAgreementTmp(vendListPricePriceTermAgreementRelationTmp);

    return basePriceRawData;
}

private void prepareVendListPriceTmp()
{
    GUPVendListPriceView vendListPriceViewWithTopRank;
    GUPVendListPriceView vendListPriceView;
    InventDim inventDimVendListPrice;
    InventDimCombination inventDimCombination;
    InventDim inventDimProductVariant;
    InventDim mergedInventDim;

    // find most specific vendor list price according to calculation date and site id
    while select AccountNum, ItemNum, InventDimId from vendListPriceViewWithTopRank
        group by AccountNum, ItemNum, InventDimId
    {
        itemsToBeCalculated.add(vendListPriceViewWithTopRank.ItemNum);
        if (InventTable::find(vendListPriceViewWithTopRank.ItemNum).hasProductDimensions())
        {
            while select vendListPriceView
                where vendListPriceView.AccountNum == vendListPriceViewWithTopRank.AccountNum
                    && vendListPriceView.ItemNum == vendListPriceViewWithTopRank.ItemNum
                    && vendListPriceView.InventDimId == vendListPriceViewWithTopRank.InventDimId
                    && (vendListPriceView.ToDate >= basePriceRawData.paramCalculationDate()
                        || vendListPriceView.ToDate == dateNull())
            join inventDimVendListPrice
                where inventDimVendListPrice.InventDimId    == vendListPriceView.InventDimId
                   && inventDimVendListPrice.InventSiteId   == basePriceRawData.paramInventSiteId()
            join inventDimCombination
                where inventDimCombination.ItemId == vendListPriceView.ItemNum
            join inventDimProductVariant
                where inventDimProductVariant.InventDimId == inventDimCombination.InventDimId
                    && (inventDimVendListPrice.InventColorId == ''  || (inventDimVendListPrice.InventColorId    && inventDimVendListPrice.InventColorId == inventDimProductVariant.InventColorId))
                    && (inventDimVendListPrice.InventSizeId == ''   || (inventDimVendListPrice.InventSizeId     && inventDimVendListPrice.InventSizeId == inventDimProductVariant.InventSizeId))
                    && (inventDimVendListPrice.InventStyleId == ''  || (inventDimVendListPrice.InventStyleId    && inventDimVendListPrice.InventStyleId == inventDimProductVariant.InventStyleId))
                    && (inventDimVendListPrice.configId == ''       || (inventDimVendListPrice.configId         && inventDimVendListPrice.configId == inventDimProductVariant.configId))
                {
                    mergedInventDim = InventDim::findOrCreate(this.mergeVendListPriceDimWithProductVariantDim(inventDimVendListPrice, inventDimProductVariant));
                    inventDimMap.insert(mergedInventDim.inventDimId, mergedInventDim);
                    this.inserVendListPriceTmp(vendListPriceView, mergedInventDim.inventDimId);
                }
        }
        else
        {
            while select vendListPriceView
                where vendListPriceView.AccountNum == vendListPriceViewWithTopRank.AccountNum
                    && vendListPriceView.ItemNum == vendListPriceViewWithTopRank.ItemNum
                    && vendListPriceView.InventDimId == vendListPriceViewWithTopRank.InventDimId
                    && (vendListPriceView.ToDate >= basePriceRawData.paramCalculationDate()
                        || vendListPriceView.ToDate == dateNull())
            join inventDimVendListPrice
                where inventDimVendListPrice.InventDimId    == vendListPriceView.InventDimId
                   && inventDimVendListPrice.InventSiteId   == basePriceRawData.paramInventSiteId()
            outer join inventDimCombination
                where inventDimCombination.ItemId == vendListPriceView.ItemNum
            outer join inventDimProductVariant
                where inventDimProductVariant.InventDimId == inventDimCombination.InventDimId
                    && (inventDimVendListPrice.InventColorId == ''  || (inventDimVendListPrice.InventColorId    && inventDimVendListPrice.InventColorId == inventDimProductVariant.InventColorId))
                    && (inventDimVendListPrice.InventSizeId == ''   || (inventDimVendListPrice.InventSizeId     && inventDimVendListPrice.InventSizeId == inventDimProductVariant.InventSizeId))
                    && (inventDimVendListPrice.InventStyleId == ''  || (inventDimVendListPrice.InventStyleId    && inventDimVendListPrice.InventStyleId == inventDimProductVariant.InventStyleId))
                    && (inventDimVendListPrice.configId == ''       || (inventDimVendListPrice.configId         && inventDimVendListPrice.configId == inventDimProductVariant.configId))
            {
                mergedInventDim = InventDim::findOrCreate(this.mergeVendListPriceDimWithProductVariantDim(inventDimVendListPrice, inventDimProductVariant));
                inventDimMap.insert(mergedInventDim.inventDimId, mergedInventDim);
                this.inserVendListPriceTmp(vendListPriceView, mergedInventDim.inventDimId);
            }
        }
    }
}

private void preparePriceTermAgreementTmp()
{
    GUPPriceTermAgreementView priceTermAgreementView;
    GUPPricingRule pricingRule;
    InventDim inventDimPriceTermAgreement;

    while select priceTermAgreementView
    join inventDimPriceTermAgreement
        where inventDimPriceTermAgreement.InventDimId == priceTermAgreementView.InventDimId
            && inventDimPriceTermAgreement.InventSiteId == basePriceRawData.paramInventSiteId()
    outer join pricingRule
        where priceTermAgreementView.PricingRule == pricingRule.RecId
    {
        if(pricingRule)
        {
            pricingRuleMap.insert(pricingRule.RecId, pricingRule);
        }
        if (inventDimPriceTermAgreement)
        {
            inventDimMap.insert(inventDimPriceTermAgreement.inventDimId, inventDimPriceTermAgreement);
        }
        this.insertPriceTermAgreementTmp(priceTermAgreementView);
    }
}

private void prepareVendListPriceAndPriceTermAgreementTmp()
{
    InventDim inventDimVendListPrice;
    InventDim inventDimPriceTermAgreement;

    select count(RecId) from vendListPriceTmp;
    int vendPriceGroups = vendListPriceTmp.RecId / ITEMS_PER_GROUP;
    select count(RecId) from priceTermAgreementTmp;
    int priceTermGroups = priceTermAgreementTmp.RecId / PRICE_TERM_PER_GROUP;
    try
    {
        // Split price term & vend price records into several smaller groups so memory could be released after each round. 
        // Running as a whole round would result in OOM for large amount of data.
        for (int priceTermGroup = 0; priceTermGroup <= priceTermGroups; priceTermGroup++)
        {
            int currPriceTerm = 0;
            while select priceTermAgreementTmp
            {
                if (currPriceTerm >= priceTermGroup * PRICE_TERM_PER_GROUP && currPriceTerm < (priceTermGroup + 1) * PRICE_TERM_PER_GROUP)
                {
                    inventDimPriceTermAgreement = inventDimMap.lookup(priceTermAgreementTmp.InventDimId);
                    Set matchedItems;
                    for (int i = 0; i <= vendPriceGroups; i++)
                    {
                        int currVendPrice = 0;
                        while select vendListPriceTmp
                            where vendListPriceTmp.AccountNum == priceTermAgreementTmp.AccountNum
                                || vendListPriceTmp.AccountCode == TableGroupAll::All
                                || priceTermAgreementTmp.AccountCode == TableGroupAll::All
                        {
                            if (currVendPrice >= i * ITEMS_PER_GROUP && currVendPrice < (i + 1) * ITEMS_PER_GROUP)
                            {
                                inventDimVendListPrice = inventDimMap.lookup(vendListPriceTmp.InventDimId);
                                GUPPricingRule agreementPricingRule;

                                if (this.checkInventDimAreMatched(inventDimVendListPrice, inventDimPriceTermAgreement))
                                {
                                    if (pricingRuleMap.exists(priceTermAgreementTmp.PricingRule))
                                    {
                                        agreementPricingRule = pricingRuleMap.lookup(priceTermAgreementTmp.PricingRule);
                                    }

                                    Query query;
                                    if (agreementPricingRule && agreementPricingRule.PriceAttributeGroupName != '')
                                    {
                                        if (agreementPricingRule.ExclusionType == GUPPricingRuleExclusionType::Product)
                                        {
                                            if (!matchedItems)
                                            {
                                                matchedItems = new Set(Types::String);
                                                query = GUPPricingObjectQueryBuilder::constructFromPricingRule(agreementPricingRule).build();

                                                QueryRun qr = new QueryRun(query);
                                                InventTable inventTable;
                                                while (qr.next())
                                                {
                                                    inventTable = qr.get(tableNum(InventTable));
                                                    if (itemsToBeCalculated.in(inventTable.ItemId))
                                                    {
                                                        matchedItems.add(inventTable.ItemId);
                                                    }
                                                }
                                            }
                                            if (matchedItems.in(vendListPriceTmp.ItemId) && this.checkItemIsMatched(vendListPriceTmp.ItemId, agreementPricingRule) && this.checkFromToDateHasOverlap(vendListPriceTmp, priceTermAgreementTmp))
                                            {
                                                this.insertVendListPriceSplitDateTmp(vendListPriceTmp, priceTermAgreementTmp);
                                                this.insertVendListPricePriceTermAgreementRelationTmp(vendListPriceTmp.RecId, priceTermAgreementTmp.RecId);
                                            }
                                        }
                                        else if (agreementPricingRule.ExclusionType == GUPPricingRuleExclusionType::ProductVariant)
                                        {
                                            if (queryMap.exists(agreementPricingRule.RecId))
                                            {
                                                query = queryMap.lookup(agreementPricingRule.RecId);
                                            }
                                            else
                                            {
                                                query = GUPPricingObjectQueryBuilder::constructFromPricingRule(agreementPricingRule).addProductVariants().build();
                                                queryMap.add(agreementPricingRule.RecId, query);
                                            }
                                            Query tmpQuery = new Query(query);
                                            this.addQueryRangeForItemId(tmpQuery, vendListPriceTmp.ItemId);
                                            this.addQueryRangeForProductVariantInclusion(tmpQuery, inventDimVendListPrice);
                                            if (this.checkProductVariantIsMatched(tmpQuery, agreementPricingRule) && this.checkFromToDateHasOverlap(vendListPriceTmp, priceTermAgreementTmp))
                                            {
                                                this.insertVendListPriceSplitDateTmp(vendListPriceTmp, priceTermAgreementTmp);
                                                this.insertVendListPricePriceTermAgreementRelationTmp(vendListPriceTmp.RecId, priceTermAgreementTmp.RecId);
                                            }
                                        }
                                        else
                                        {
                                            throw error("@GlobalUnifiedPricing:GUPErrorForUnsupportedPricingAttributeSourceType");
                                        }
                                    }
                                    else
                                    {
                                        this.insertVendListPriceSplitDateTmp(vendListPriceTmp, priceTermAgreementTmp);
                                        this.insertVendListPricePriceTermAgreementRelationTmp(vendListPriceTmp.RecId, priceTermAgreementTmp.RecId);
                                    }
                                }
                                else if (currVendPrice > (i + 1) * ITEMS_PER_GROUP)
                                {
                                    break;
                                }
                            }
                            currVendPrice++;
                        }
                    }
                }
                currPriceTerm++;
                inventDimMatchResultTmp = null;
            }
        }

    }
    catch (Exception::Error)
    {
        throw error("@SYS19457");
    }
}

private void checkVendListSplitDateAndInsert(RecId vendListPriceTmpRecId, date intermediumDate, boolean allowDuplicate = false)
{
    if (!allowDuplicate)
    {
        select vendListPriceSplitDateTmp 
            where vendListPriceSplitDateTmp.IntermediumDate == intermediumDate 
                && vendListPriceSplitDateTmp.VendListPriceTmpRecId == vendListPriceTmpRecId;
        if (vendListPriceSplitDateTmp)
        {
            return;
        }
    }

    vendListPriceSplitDateTmp.VendListPriceTmpRecId = vendListPriceTmpRecId;
    vendListPriceSplitDateTmp.IntermediumDate = intermediumDate;
    vendListPriceSplitDateTmp.insert();
}

private void insertVendListPriceSplitDateTmp(GUPVendListPriceTmp _vendListPriceTmp, GUPPriceTermAgreementTmp _priceTermAgreementTmp)
{
    vendListPriceSplitDateTmp.clear();

    if (!vendListPriceTmp.ToDate && !_priceTermAgreementTmp.ValidTo && _vendListPriceTmp.FromDate < _priceTermAgreementTmp.ValidFrom)
    {
        // both to dates are null: only need to split when price starts earlier
        this.checkVendListSplitDateAndInsert(_vendListPriceTmp.RecId, _priceTermAgreementTmp.ValidFrom - 1);
    }
    else if (_priceTermAgreementTmp.ValidTo 
        && (!_vendListPriceTmp.ToDate || _vendListPriceTmp.ToDate > _priceTermAgreementTmp.ValidTo)
        && _priceTermAgreementTmp.ValidTo >= _vendListPriceTmp.FromDate)
    {
        // when to date of price is later than agreement, or when price to date is null: 2 situations
        // caution: second requirement is to exclude the situation in which there is no overlap
        if (_priceTermAgreementTmp.ValidFrom <= _vendListPriceTmp.FromDate)
        {
            // agreement starts earlier than price or starts at the same time as price: only needs 1 split
            this.checkVendListSplitDateAndInsert(_vendListPriceTmp.RecId, _priceTermAgreementTmp.ValidTo);
        }
        else
        {
            // agreement starts later than price: needs 2 splits
            this.checkVendListSplitDateAndInsert(_vendListPriceTmp.RecId, _priceTermAgreementTmp.ValidFrom - 1, _priceTermAgreementTmp.ValidFrom == _priceTermAgreementTmp.ValidTo);

            this.checkVendListSplitDateAndInsert(_vendListPriceTmp.RecId, _priceTermAgreementTmp.ValidTo, _priceTermAgreementTmp.ValidFrom == _priceTermAgreementTmp.ValidTo);
        }
    }
    else if (_vendListPriceTmp.ToDate 
        && (!_priceTermAgreementTmp.ValidTo || _priceTermAgreementTmp.ValidTo > _vendListPriceTmp.ToDate)
        && _vendListPriceTmp.ToDate >= _priceTermAgreementTmp.ValidFrom)
    {
        // when to date of agreement is later than price, or when agreement to date is null: only needs to split when price starts earlier
        // caution: second requirement is to exclude the situation in which there is no overlap
        if (_vendListPriceTmp.FromDate < _priceTermAgreementTmp.ValidFrom)
        {
            this.checkVendListSplitDateAndInsert(_vendListPriceTmp.RecId, _priceTermAgreementTmp.ValidFrom - 1);
        }
    }
}

private boolean checkFromToDateHasOverlap(GUPVendListPriceTmp _vendListPriceTmp, GUPPriceTermAgreementTmp _priceTermAgreementTmp)
{
    return (_vendListPriceTmp.FromDate <= _priceTermAgreementTmp.ValidTo || !_priceTermAgreementTmp.ValidTo)
        && (_vendListPriceTmp.ToDate >= _priceTermAgreementTmp.ValidFrom || !_vendListPriceTmp.ToDate);
}

private InventDim mergeVendListPriceDimWithProductVariantDim(InventDim _inventDimVendListPrice, InventDim _inventDimProductVariant)
{
    if (!_inventDimProductVariant)
    {
        return _inventDimVendListPrice;
    }
    InventDim mergedInventDim;
    ListEnumerator enumerator = InventDim::dimFieldListEnumerator();
    FieldId inventDimFieldId;

    while (enumerator.moveNext())
    {
        inventDimFieldId = enumerator.current();
        mergedInventDim.(inventDimFieldId) = _inventDimVendListPrice.(inventDimFieldId) ? _inventDimVendListPrice.(inventDimFieldId) : _inventDimProductVariant.(inventDimFieldId);
    }

    return mergedInventDim;
}

private boolean checkInventDimAreMatched(InventDim _inventDimVendListPrice, InventDim _inventDimPriceTermAgreement)
{
    select firstonly inventDimMatchResultTmp where inventDimMatchResultTmp.SourceInventDim == _inventDimVendListPrice.inventDimId
        && inventDimMatchResultTmp.DestInventDim == _inventDimPriceTermAgreement.inventDimId;
    if (inventDimMatchResultTmp)
    {
        return inventDimMatchResultTmp.Match;
    }

    InventDimParm inventDimParmVendListPrice;
    InventDimParm inventDimParmPriceTermAgreement;
    boolean inventDimOfPriceTermAgreementContainsVendListPrice;
    boolean valuesOfInventDimIntersectionAreIdentical;

    //check if price term agreement inventory dimensions contains vend list price inventory dimensions and values are identical for intersection
    inventDimParmVendListPrice.initFromInventDim(_inventDimVendListPrice);
    inventDimParmPriceTermAgreement.initFromInventDim(_inventDimPriceTermAgreement);
    inventDimOfPriceTermAgreementContainsVendListPrice = InventDimParm::isInventDimParmEqual(inventDimParmPriceTermAgreement,
            InventDimParm::andParms(inventDimParmVendListPrice, inventDimParmPriceTermAgreement));
    valuesOfInventDimIntersectionAreIdentical = InventDim::isInventDimParmEqual(_inventDimVendListPrice, _inventDimPriceTermAgreement, inventDimParmPriceTermAgreement, false);
    boolean result = inventDimOfPriceTermAgreementContainsVendListPrice && valuesOfInventDimIntersectionAreIdentical;

    inventDimMatchResultTmp.clear();
    inventDimMatchResultTmp.SourceInventDim = _inventDimVendListPrice.inventDimId;
    inventDimMatchResultTmp.DestInventDim = _inventDimPriceTermAgreement.inventDimId;
    inventDimMatchResultTmp.Match = result;
    inventDimMatchResultTmp.insert();
    return result;
}

private Query addQueryRangeForItemId(Query _query, ItemId _itemId)
{
    str qbdrName;
    QueryBuildDataSource qbdrOrigInventTable;

    qbdrOrigInventTable = _query.dataSourceTable(tableNum(InventTable));
    qbdrName = qbdrOrigInventTable.name();

    //here is a trick, use another table filed to introduce the AND relationship for ItemId
    //as add multiple range for ItemId will by default use OR relationship that is not we want
    qbdrOrigInventTable.addRange(fieldNum(InventTable, Product)).value(
        strFmt('(%1.%2 == "%3")',
        qbdrName,
        fieldStr(InventTable, ItemId),
        SysQuery::value(_itemId)));

    return _query;
}

private Query initQueryByProductVariant(GUPPricingRule _pricingRule, ItemId _itemId, InventDim _inventDimVendListPrice)
{
    Query query = GUPPricingObjectQueryBuilder::constructFromPricingRule(_pricingRule).addProductVariants().build();

    this.addQueryRangeForProductVariantInclusion(query, _inventDimVendListPrice);

    return query;
}

private Query addQueryRangeForProductVariantInclusion(Query _query, InventDim _inventDimVendListPrice)
{
    this.addQueryRangeForSizeInclusion(_query, _inventDimVendListPrice.InventSizeId);
    this.addQueryRangeForColorInclusion(_query, _inventDimVendListPrice.InventColorId);
    this.addQueryRangeForStyleInclusion(_query, _inventDimVendListPrice.InventStyleId);
    this.addQueryRangeForConfigurationInclusion(_query, _inventDimVendListPrice.configId);

    return _query;
}

private Query addQueryRangeForSizeInclusion(Query _query, EcoResItemSizeName _inventSizeId)
{
    QueryBuildDataSource qbds = _query.dataSourceTable(tableNum(EcoResDistinctProductVariant));
    if (_inventSizeId && qbds)
    {
        QueryBuildDataSource qbdsVariantSize = qbds.addDataSource(tableNum(EcoResProductVariantSize));
        qbdsVariantSize.joinMode(JoinMode::ExistsJoin);
        qbdsVariantSize.addLink(fieldNum(EcoResDistinctProductVariant, RecId), fieldNum(EcoResProductVariantSize, DistinctProductVariant));

        QueryBuildDataSource qbdsSize = qbdsVariantSize.addDataSource(tableNum(EcoResSize));
        qbdsSize.joinMode(JoinMode::InnerJoin);
        qbdsSize.addLink(fieldNum(EcoResProductVariantSize, Size), fieldNum(EcoResSize, RecId));
        qbdsSize.addRange(fieldNum(EcoResSize, Name)).value(queryValue(_inventSizeId));
    }
    return _query;
}

private Query addQueryRangeForColorInclusion(Query _query, EcoResItemColorName _inventColorId)
{
    QueryBuildDataSource qbds = _query.dataSourceTable(tableNum(EcoResDistinctProductVariant));
    if (_inventColorId && qbds)
    {
        QueryBuildDataSource qbdsVariantColor = qbds.addDataSource(tableNum(EcoResProductVariantColor));
        qbdsVariantColor.joinMode(JoinMode::ExistsJoin);
        qbdsVariantColor.addLink(fieldNum(EcoResDistinctProductVariant, RecId), fieldNum(EcoResProductVariantColor, DistinctProductVariant));

        QueryBuildDataSource qbdsColor = qbdsVariantColor.addDataSource(tableNum(EcoResColor));
        qbdsColor.joinMode(JoinMode::InnerJoin);
        qbdsColor.addLink(fieldNum(EcoResProductVariantColor, Color), fieldNum(EcoResColor, RecId));
        qbdsColor.addRange(fieldNum(EcoResColor, Name)).value(queryValue(_inventColorId));
    }
    return _query;
}

private Query addQueryRangeForStyleInclusion(Query _query, EcoResItemStyleName _inventStyleId)
{
    QueryBuildDataSource qbds = _query.dataSourceTable(tableNum(EcoResDistinctProductVariant));
    if (_inventStyleId && qbds)
    {
        QueryBuildDataSource qbdsVariantStyle = qbds.addDataSource(tableNum(EcoResProductVariantStyle));
        qbdsVariantStyle.joinMode(JoinMode::ExistsJoin);
        qbdsVariantStyle.addLink(fieldNum(EcoResDistinctProductVariant, RecId), fieldNum(EcoResProductVariantStyle, DistinctProductVariant));

        QueryBuildDataSource qbdsStyle = qbdsVariantStyle.addDataSource(tableNum(EcoResStyle));
        qbdsStyle.joinMode(JoinMode::InnerJoin);
        qbdsStyle.addLink(fieldNum(EcoResProductVariantStyle, Style), fieldNum(EcoResStyle, RecId));
        qbdsStyle.addRange(fieldNum(EcoResStyle, Name)).value(queryValue(_inventStyleId));
    }
    return _query;
}

private Query addQueryRangeForConfigurationInclusion(Query _query, EcoResItemConfigurationName _configId)
{
    QueryBuildDataSource qbds = _query.dataSourceTable(tableNum(EcoResDistinctProductVariant));
    if (_configId && qbds)
    {
        QueryBuildDataSource qbdsVariantConfiguration = qbds.addDataSource(tableNum(EcoResProductVariantConfiguration));
        qbdsVariantConfiguration.joinMode(JoinMode::ExistsJoin);
        qbdsVariantConfiguration.addLink(fieldNum(EcoResDistinctProductVariant, RecId), fieldNum(EcoResProductVariantConfiguration, DistinctProductVariant));

        QueryBuildDataSource qbdsConfiguration = qbdsVariantConfiguration.addDataSource(tableNum(EcoResConfiguration));
        qbdsConfiguration.joinMode(JoinMode::InnerJoin);
        qbdsConfiguration.addLink(fieldNum(EcoResProductVariantConfiguration, Configuration), fieldNum(EcoResConfiguration, RecId));
        qbdsConfiguration.addRange(fieldNum(EcoResConfiguration, Name)).value(queryValue(_configId));
    }
    return _query;
}

private boolean checkItemIsMatched(str _item, GUPPricingRule _agreementPricingRule)
{
    GUPPricingRuleExclusion ruleExclusion;
    select firstonly ruleExclusion
            where ruleExclusion.RuleId == _agreementPricingRule.RecId && ruleExclusion.Exclusion == _item;
    return !ruleExclusion;
}

private boolean checkProductVariantIsMatched(Query _query, GUPPricingRule _agreementPricingRule)
{
    QueryRun queryRun = new QueryRun(_query);
    while (queryRun.next())
    {
        EcoResDistinctProductVariant ecoResDistinctProductVariant = queryRun.get(tableNum(EcoResDistinctProductVariant));
        GUPPricingRuleExclusion ruleExclusion;
        select firstonly ruleExclusion
            where ruleExclusion.RuleId == _agreementPricingRule.RecId && ruleExclusion.Exclusion == int2Str(ecoResDistinctProductVariant.RecId);
        if (!ruleExclusion)
        {
            return true;
        }
    }
    return false;
}

private void inserVendListPriceTmp(GUPVendListPriceView _vendListPriceView, InventDimId _mergedInventDimId)
{
    vendListPriceTmp.clear();
    vendListPriceTmp.AccountCode = _vendListPriceView.AccountCode;
    vendListPriceTmp.AccountNum = _vendListPriceView.AccountNum;
    vendListPriceTmp.Amount = _vendListPriceView.Amount;
    vendListPriceTmp.Currency = _vendListPriceView.Currency;
    vendListPriceTmp.FromDate = _vendListPriceView.FromDate;
    vendListPriceTmp.ToDate = _vendListPriceView.ToDate;
    vendListPriceTmp.InventDimId = _mergedInventDimId;
    vendListPriceTmp.ItemId = _vendListPriceView.ItemNum;
    vendListPriceTmp.Markup = _vendListPriceView.Markup;
    vendListPriceTmp.PriceUnit = _vendListPriceView.PriceUnit;
    vendListPriceTmp.UnitId = _vendListPriceView.UnitId;
    vendListPriceTmp.insert();
}

private void insertPriceTermAgreementTmp(GUPPriceTermAgreementView _priceTermAgreementView)
{
    priceTermAgreementTmp.clear();
    priceTermAgreementTmp.AccountCode = _priceTermAgreementView.AccountCode;
    priceTermAgreementTmp.AccountNum = _priceTermAgreementView.AccountNum;
    priceTermAgreementTmp.CalculateBasePricePurchase = _priceTermAgreementView.CalculateBasePricePurchase;
    priceTermAgreementTmp.CalculateBasePriceInventory = _priceTermAgreementView.CalculateBasePriceInventory;
    priceTermAgreementTmp.CalculateBasePriceSales = _priceTermAgreementView.CalculateBasePriceSales;
    priceTermAgreementTmp.CalculateMethod = _priceTermAgreementView.CalculateMethod;
